transcripcion.texto:
```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "televisor 4K smart",
        "category": "televisores",
        "attributes": {"resolucion": "4K"},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id", "$s1.2.id"]
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "$s2.mas_barato",
        "limit": 3
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "¡Hola! Para ver películas en 4K en el living con presupuesto acotado, te recomiendo el {nombre_barato} <<rec:{id_barato}>> a ${precio_barato} CLP, que es la opción más económica entre las disponibles en 4K. También puedes considerar el {nombre_eval} <<rec:{id_eval}>> si buscas la mejor evaluación. Comparando ambas opciones: <<cmp:{id_barato},{id_eval}>>. Reseñas de la opción más accesible: {resenas}",
      "vars": {
        "nombre_barato": "$s2.productos.0.name",
        "id_barato": "$s2.mas_barato",
        "precio_barato": "$s2.productos.0.price_clp",
        "nombre_eval": "$s2.productos.0.name",
        "id_eval": "$s2.mejor_evaluado",
        "resenas": "$s3"
      }
    }
  ]
}
